mapper.select:
SELECT 
FROM money_log


        AND user_id = #{query.userId}


        AND username LIKE CONCAT('%', #{query.username}, '%')


        AND user_type = #{query.userType}


        AND operation_type = #{query.operationType}


        AND currency = #{query.currency}


        AND related_order_no LIKE CONCAT('%', #{query.relatedOrderNo}, '%')


        AND status = #{query.status}


        AND created_at >= #{query.startTime}


        AND created_at <= #{query.endTime}


        AND ABS(amount) >= #{query.minAmount}


        AND ABS(amount) <= #{query.maxAmount}


        AND (username LIKE CONCAT('%', #{query.keyword}, '%') 
             OR description LIKE CONCAT('%', #{query.keyword}, '%')
             OR remark LIKE CONCAT('%', #{query.keyword}, '%'))




        ORDER BY ${query.sortField}

            ${query.sortOrder}



        ORDER BY created_at DESC

SELECT 
    COUNT(*) as total_count,
    COALESCE(SUM(CASE WHEN amount > 0 THEN amount ELSE 0 END), 0) as total_income,
    COALESCE(SUM(CASE WHEN amount < 0 THEN ABS(amount) ELSE 0 END), 0) as total_expense,
    COALESCE(SUM(amount), 0) as net_amount
FROM money_log
WHERE user_id = #{userId}

    AND created_at >= #{startTime}


    AND created_at <= #{endTime}

AND status = 1

SELECT operation_type, COUNT(*) as count, COALESCE(SUM(ABS(amount)), 0) as total_amount FROM money_log WHERE status = 1
AND created_at >= #{startTime}
AND created_at <= #{endTime}
GROUP BY operation_type ORDER BY total_amount DESC

SELECT COALESCE(SUM(ABS(amount)), 0)
FROM money_log
WHERE status = 1

    AND created_at >= #{startTime}


    AND created_at <= #{endTime}


    AND operation_type = #{operationType}
